"""In-memory url store. See api/API.md."""


class Store:
    def __init__(self):
        self._urls: dict[int, str] = {}
        self._ids: dict[str, int] = {}
        self._hits: dict[int, int] = {}

    def add(self, url: str) -> int:
        if url in self._ids:
            return self._ids[url]
        id = len(self._urls) + 1
        self._urls[id] = url
        self._ids[url] = id
        self._hits[id] = 0
        return id

    def get(self, id: int) -> str | None:
        return self._urls.get(id)

    def hit(self, id: int) -> int:
        self._hits[id] = self.hits(id) + 1
        return self._hits[id]

    def hits(self, id: int) -> int:
        if id not in self._hits:
            raise KeyError(id)
        return self._hits[id]

    def __len__(self) -> int:
        return len(self._urls)
